class TaskService:
    # ...
    def get_prioritized_tasks(self, user_id: int, use_eisenhower: bool = False) -> List[Task]:
        tasks = self.db.query(Task).filter(Task.owner_id == user_id).all()
        if use_eisenhower:
            return self._prioritize_tasks_eisenhower(tasks)
        else:
            return self._prioritize_tasks_default(tasks)

    def _prioritize_tasks_default(self, tasks: List[Task]) -> List[Task]:
        # ... existing or refactored default logic
        return sorted(tasks, key=lambda t: t.due_date)

    def _prioritize_tasks_eisenhower(self, tasks: List[Task]) -> List[Task]:
        # New logic: Urgent & Important first
        return sorted(tasks, key=lambda t: (not (t.is_urgent and t.is_important)), t.due_date)
